import { useEffect, useMemo, useState } from "react";
import MiniSearch from "minisearch";
import getDiscourseNodes from "~/utils/getDiscourseNodes";
import { searchDiscourseNodes } from "~/utils/searchDiscourseNodes";
import {
  matchesTypeFilter,
  searchDiscourseNodesWithMiniSearch,
  sortSearchResults,
  type ScoredSearchResult,
  type SearchResult,
  type SortConfig,
} from "./utils";

export type SearchIndex = {
  miniSearch: MiniSearch<SearchResult & { id: string }>;
  allResults: SearchResult[];
};

type UseAdvancedNodeSearchResultsArgs = {
  debouncedSearchTerm: string;
  selectedNodeTypeIds: string[];
  sort: SortConfig;
  isIndexLoading: boolean;
  indexError: boolean;
  searchIndex: SearchIndex | null;
  dockedQuery?: string;
  dockedResults?: SearchResult[];
};

export const useAdvancedNodeSearchResults = ({
  debouncedSearchTerm,
  selectedNodeTypeIds,
  sort,
  isIndexLoading,
  indexError,
  searchIndex,
  dockedQuery,
  dockedResults,
}: UseAdvancedNodeSearchResultsArgs): {
  results: SearchResult[];
  isSearching: boolean;
} => {
  // An empty persisted result set is not a usable cache: the docked panel also
  // persists the transient [] published while an async search is in flight.
  const hasUsableDockedResults = useMemo(
    () =>
      dockedQuery !== undefined &&
      debouncedSearchTerm.trim() === dockedQuery.trim() &&
      !!dockedResults &&
      dockedResults.length > 0,
    [debouncedSearchTerm, dockedQuery, dockedResults],
  );

  const [unsortedScoredResults, setUnsortedScoredResults] = useState<
    ScoredSearchResult[]
  >([]);
  const [isSearching, setIsSearching] = useState(false);

  useEffect(() => {
    if (hasUsableDockedResults) {
      setUnsortedScoredResults([]);
      setIsSearching(false);
      return;
    }

    if (!debouncedSearchTerm) {
      setUnsortedScoredResults([]);
      setIsSearching(false);
      return;
    }

    if (isIndexLoading || indexError || !searchIndex) {
      setUnsortedScoredResults([]);
      setIsSearching(false);
      return;
    }

    setUnsortedScoredResults([]);
    setIsSearching(true);
    let cancelled = false;
    const typeFilter = selectedNodeTypeIds.length
      ? selectedNodeTypeIds
      : undefined;
    const discourseNodes = getDiscourseNodes().filter(
      (node) =>
        node.backedBy === "user" &&
        (!typeFilter || typeFilter.includes(node.type)),
    );
    const resultsByUid = new Map(
      searchIndex.allResults.map((result) => [result.uid, result]),
    );
    const allowedTypes = typeFilter ? new Set(typeFilter) : null;
    const candidateUids = new Set(
      searchIndex.allResults
        .filter(
          (result) =>
            !!result.candidate &&
            (!allowedTypes || matchesTypeFilter(result, allowedTypes)),
        )
        .map((result) => result.uid),
    );

    const runMiniSearch = (): ScoredSearchResult[] =>
      searchDiscourseNodesWithMiniSearch({
        miniSearch: searchIndex.miniSearch,
        allResults: searchIndex.allResults,
        searchTerm: debouncedSearchTerm,
        typeFilter,
      });

    void searchDiscourseNodes({
      nodeTypes: discourseNodes,
      query: debouncedSearchTerm,
      resultsByUid,
      runMiniSearch,
      candidateUids,
    })
      .then((results) => {
        if (cancelled) return;
        setUnsortedScoredResults(results);
      })
      .catch(() => {
        if (cancelled) return;
        try {
          setUnsortedScoredResults(runMiniSearch());
        } catch {
          setUnsortedScoredResults([]);
        }
      })
      .finally(() => {
        if (!cancelled) setIsSearching(false);
      });

    return () => {
      cancelled = true;
    };
  }, [
    debouncedSearchTerm,
    hasUsableDockedResults,
    indexError,
    isIndexLoading,
    searchIndex,
    selectedNodeTypeIds,
  ]);

  const results = useMemo(
    () => sortSearchResults({ scoredResults: unsortedScoredResults, sort }),
    [unsortedScoredResults, sort],
  );

  if (hasUsableDockedResults && dockedResults) {
    return { results: dockedResults, isSearching: false };
  }

  return { results, isSearching };
};
import type { DiscourseNode } from "~/utils/getDiscourseNodes";
import {
  combineSemanticAndMiniSearchResults,
  MAX_RESULTS,
  toScoredSearchResultFromSemantic,
  type ScoredSearchResult,
  type SearchResult,
} from "~/utils/discourseNodeSearchTypes";
import { runRoamSemanticSearch } from "~/utils/discourseNodeSearchProviders";

export const SEMANTIC_SEARCH_MIN_DISCOURSE_RESULTS = 5;

export type {
  DiscourseNodeSearchSource,
  ScoredSearchResult,
  SearchResult,
} from "~/utils/discourseNodeSearchTypes";

export const isRoamSemanticSearchEnabled = (): boolean =>
  window.roamAlphaAPI.data.semanticSearchEnabled();

const runMiniSearchSafely = (
  runMiniSearch: () => ScoredSearchResult[],
): ScoredSearchResult[] => {
  try {
    return runMiniSearch();
  } catch {
    return [];
  }
};

export const searchDiscourseNodes = async ({
  nodeTypes,
  query,
  resultsByUid,
  runMiniSearch,
  candidateUids,
}: {
  nodeTypes: DiscourseNode[];
  query: string;
  resultsByUid: Map<string, SearchResult>;
  runMiniSearch: () => ScoredSearchResult[];
  candidateUids?: Set<string>;
}): Promise<ScoredSearchResult[]> => {
  const trimmedQuery = query.trim();
  if (!trimmedQuery) return [];

  let results: ScoredSearchResult[];

  if (!isRoamSemanticSearchEnabled()) {
    results = runMiniSearchSafely(runMiniSearch);
  } else {
    try {
      const providerResult = await runRoamSemanticSearch({
        nodeTypes,
        query: trimmedQuery,
        candidateUids,
      });
      const semanticResults = providerResult.filteredResults.map((item) =>
        toScoredSearchResultFromSemantic({
          uid: item.uid,
          title: item.text,
          type: item.type,
          nodeTypeLabel: item.nodeTypeLabel,
          score: item.score ?? 0,
          resultsByUid,
        }),
      );

      results =
        providerResult.filteredResultCount >=
        SEMANTIC_SEARCH_MIN_DISCOURSE_RESULTS
          ? semanticResults
          : combineSemanticAndMiniSearchResults({
              semantic: semanticResults,
              miniSearch: runMiniSearchSafely(runMiniSearch),
            });
    } catch {
      results = runMiniSearchSafely(runMiniSearch);
    }
  }

  return results.slice(0, MAX_RESULTS);
};
